import { Scene, Camera2DController, Vec3 } from "retiam";

export class My2DScene extends Scene {
    public async run() {
        // Initialize 2D controller with smooth damping & momentum
        const controller = new Camera2DController(this, this.camera, {
            bounds: { minX: -500, maxX: 500, minY: -500, maxY: 500 },
            moveSpeed: 50.0,
            damping: 12.0,
            inertiaFriction: 0.92,
            zoomSpeed: 1.0,
            minZoom: 0.01,
            maxZoom: 10000.0,
            orthoScale: 100
        });
    }
}

